import { loadStripe } from '@stripe/stripe-js';
import React from 'react';
import toast from 'react-hot-toast';
import { FaShareSquare } from "react-icons/fa";
import { MdArrowRight } from "react-icons/md";
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { addToCart } from '../../../slices/cartSlice';

const CourseBuyCard = ({course, setConfirmationModal}) => {
  const {token} = useSelector((state)=> state.auth);
  const {user} = useSelector((state)=> state.profile);
  const {cart} = useSelector((state)=>state.cart);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const handleBuyCourse = async () => {
    if (!token || user?.accountType !== "Student") {
      setConfirmationModal(true);
      return;
    }

    try {
      const stripe = await loadStripe(process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY);

      if (!stripe) {
        toast.error("Payment system initialization failed");
        return;
      }

      // Format the course data for the API
      const courseData = {
        courseId: course._id,
        courseName: course.courseName,
        price: course.price,
      };

      const response = await fetch(`${process.env.REACT_APP_BASE_URL}/payment/create-checkout-session`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`,
        },
        body: JSON.stringify({
          products: [courseData],
          userId: user._id,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || "Failed to create checkout session");
      }

      if (!data.id) {
        throw new Error("Invalid response from payment server");
      }

      const { error } = await stripe.redirectToCheckout({
        sessionId: data.id
      });

      if (error) {
        throw new Error(error.message);
      }
    } catch (error) {
      console.error("Payment error:", error);
      toast.error(error.message || "Payment failed. Please try again.");
    }
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    toast.success('Link copied to your clipboard')
  }

  const addToCartHandler = () => {
    if(user && user.accountType === 'Student'){
      dispatch(addToCart(course))
    } else {
      toast.error("Only students are allowed to buy courses")
    }
  }

  return (
    <div className='text-white flex flex-col gap-2'>
      <div className='flex flex-col gap-2'>
        <img src={course?.thumbnail} alt='courseImg' className='rounded-lg'/>
        <h1 className='self-start text-2xl font-bold'>{`Rs. ${course?.price}`}</h1>
      </div>
      <div className='flex flex-col gap-3'>
        <button className='bg-yellow-50 w-full text-black py-2 px-4 rounded-md' 
          onClick={
            user && course?.studentsEnrolled?.includes(user?._id) 
              ? () => navigate('/dashboard/enrolled-courses')
              : handleBuyCourse
          }>
          {user && course?.studentsEnrolled?.includes(user?._id) ? 'Go to Course' : 'Buy Now'}
        </button>
        {!user || !course?.studentsEnrolled?.includes(user?._id) ? (
          cart?.find((courseInCart) => courseInCart?._id === course?._id) ? (
            <button 
              onClick={() => navigate('/dashboard/cart')} 
              className='bg-richblack-800 rounded-md w-full px-3 py-2'>
              View in Cart
            </button>
          ) : (
            <button 
              onClick={addToCartHandler} 
              className='bg-richblack-800 rounded-md w-full px-3 py-2'>
              Add to Cart
            </button>
          )
        ) : null}
      </div>
      <p className='self-center text-richblack-300'>30 Days Money Back Guarantee</p>
      <div>
        <h2 className='text-lg'>This Course Includes:- </h2>
        <ul className='text-caribbeangreen-200 flex flex-col gap-2'>
          <li className='flex gap-1 items-center'><MdArrowRight /><span>8 hours of lectures</span></li>
          <li className='flex gap-1 items-center'><MdArrowRight /><span>End to end projects</span></li>
        </ul>
      </div>
      <button 
        className='mt-3 flex gap-3 items-center text-yellow-100 justify-center' 
        onClick={handleShare}>
        <FaShareSquare />
        <span>Share</span>
      </button>
    </div>
  );
}

export default CourseBuyCard;
